CREATE OR ALTER PROCEDURE [dbo].[uspApprovalRequest_GetAll] (
	@SearchText NVARCHAR(MAX) = NULL
	, @BusinessType NVARCHAR(MAX) = NULL
	, @BusinessId UNIQUEIDENTIFIER = NULL
	, @RequestStatus NVARCHAR(MAX) = NULL
	, @Page INT = 1
	, @PageSize INT = 10
	, @SortField NVARCHAR(100) = NULL
	, @SortOrder NVARCHAR(20) = NULL)
AS
BEGIN
	SET NOCOUNT ON;
	IF @Page IS NULL OR @Page < 1 SET @Page = 1;
	IF @PageSize IS NULL OR @PageSize < 1 SET @PageSize = 10;
	IF @PageSize > 1000 SET @PageSize = 1000;

	;WITH TempResult AS
	(
		SELECT
			t.[Id]
			, t.[RequestNo]
			, t.[BusinessType]
			, t.[BusinessId]
			, t.[RequestedBy]
			, t.[RequestedAt]
			, t.[RequestStatus]
			, t.[CurrentStepNo]
			, t.[PriorityCode]
			, t.[DueAt]
			, t.[PayloadJson]
			, t.[CorrelationId]
			, t.[CompletedAt]
			, t.[CreatedDate]
		FROM [dbo].[ApprovalRequest] AS t
		
		WHERE (ISNULL(@SearchText, '') = '' OR t.[RequestNo] LIKE CONCAT('%', @SearchText, '%') OR t.[PriorityCode] LIKE CONCAT('%', @SearchText, '%'))
			AND (ISNULL(@BusinessType, '') = '' OR t.[BusinessType] = @BusinessType)
			AND (@BusinessId IS NULL OR t.[BusinessId] = @BusinessId)
			AND (ISNULL(@RequestStatus, '') = '' OR t.[RequestStatus] = @RequestStatus)
			AND t.IsDeleted = 0
	),
	TempCount (TotalRow) AS (SELECT COUNT(*) FROM TempResult)
	SELECT r.*, c.TotalRow
	FROM TempResult AS r CROSS JOIN TempCount AS c
	ORDER BY
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'requestNo' THEN r.[RequestNo] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'requestNo' THEN r.[RequestNo] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'businessType' THEN r.[BusinessType] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'businessType' THEN r.[BusinessType] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'businessId' THEN r.[BusinessId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'businessId' THEN r.[BusinessId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'requestedBy' THEN r.[RequestedBy] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'requestedBy' THEN r.[RequestedBy] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'requestedAt' THEN r.[RequestedAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'requestedAt' THEN r.[RequestedAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'requestStatus' THEN r.[RequestStatus] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'requestStatus' THEN r.[RequestStatus] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'currentStepNo' THEN r.[CurrentStepNo] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'currentStepNo' THEN r.[CurrentStepNo] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'priorityCode' THEN r.[PriorityCode] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'priorityCode' THEN r.[PriorityCode] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'dueAt' THEN r.[DueAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'dueAt' THEN r.[DueAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'payloadJson' THEN r.[PayloadJson] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'payloadJson' THEN r.[PayloadJson] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'correlationId' THEN r.[CorrelationId] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'correlationId' THEN r.[CorrelationId] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'completedAt' THEN r.[CompletedAt] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'completedAt' THEN r.[CompletedAt] END DESC,
		CASE WHEN @SortOrder = 'ascend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END ASC,
		CASE WHEN @SortOrder = 'descend' AND @SortField = 'createdDate' THEN r.[CreatedDate] END DESC,
		r.[CreatedDate] DESC
	OFFSET (@PageSize * (@Page - 1)) ROWS FETCH NEXT @PageSize ROWS ONLY
	OPTION (RECOMPILE);
END
